    public EquityGrant testCreate() throws Throwable {
    EquityGrant entity = null;

    LOGGER.info( "EquityGrantTest:testCreate()" );
    LOGGER.info( "-- Attempting to create a EquityGrant");

    StringBuilder msg = new StringBuilder( "-- Failed to create a EquityGrant" );

    try {
        entity = service.createEquityGrant( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getEquityGrantId();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a EquityGrant with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

