    /**
     * Tests getting all EquityGrants.
     *
     * @return    Collection
     */
    public List<EquityGrant> testGetAll() throws Throwable {
    LOGGER.info( "EquityGrantTest:testGetAll() - Retrieving Collection of EquityGrants:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all EquityGrant : " );
    List<EquityGrant> collection  = null;

    try {
        // call the static get method on the EquityGrantService
        collection = service.getAllEquityGrant();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            EquityGrant currEntity  = null;
            Iterator<EquityGrant> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getEquityGrantId(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

